MonarchButton(text = {{trigger}}, onClick = { open = true }, variant = MonarchButtonVariant.Primary)
if (open) {
    MonarchBottomSheet(
        onDismissRequest = { open = false },
        title = {{title}},
        description = {{description}},
        dismissible = !sending,
    ) {
        Column(
            modifier = Modifier.verticalScroll(rememberScrollState()),
            verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4),
        ) {
            MonarchTagInput(
                tags = emails,
                onTagsChange = {
                    emails = it
                    fieldError = null
                    failures = failures.filterKeys { email -> email in it }
                },
                label = {{emails.label}},
                required = true,
                removeIcon = {
                    MonarchIcon(imageVector = SampleIcons.Close, contentDescription = null)
                },
                enabled = !sending,
                placeholder = {{emails.placeholder}},
                helperText = {{emails.helper}},
                errorText = fieldError,
                separators = setOf(',', ' ', '\n'),
                maxCount = 50,
                normalize = { it.trim().removePrefix("<").removeSuffix(">") },
                validate = { tag, _ -> if (emailPattern.matches(tag)) null else "“$tag” is not an email address." },
            )
            if (failures.isNotEmpty()) {
                MonarchInlineNotice(
                    title = "${failures.size} addresses couldn’t be invited",
                    message = failures.entries.joinToString("\n") { (email, reason) -> "$email: $reason" },
                    tone = MonarchTone.Danger,
                )
            }
            MonarchRolePicker(
                roles = listOf(
                    MonarchRoleOption({{role.options.0.value}}, title = {{role.options.0.label}}, description = {{role.options.0.description}}),
                    MonarchRoleOption({{role.options.1.value}}, title = {{role.options.1.label}}, description = {{role.options.1.description}}),
                    MonarchRoleOption({{role.options.2.value}}, title = {{role.options.2.label}}, description = {{role.options.2.description}}),
                ),
                selected = role,
                onSelect = { role = it },
                layout = MonarchRolePickerLayout.Compact,
                enabled = !sending,
                label = {{role.label}},
                required = true,
            )
            @OptIn(ExperimentalMonarchApi::class)
            MonarchAppAccessPicker(
                apps = listOf(
                    MonarchAppAccessOption({{apps.options.0.id}}, {{apps.options.0.name}}, description = {{apps.options.0.description}}),
                    MonarchAppAccessOption({{apps.options.1.id}}, {{apps.options.1.name}}, description = {{apps.options.1.description}}),
                    MonarchAppAccessOption({{apps.options.2.id}}, {{apps.options.2.name}}, description = {{apps.options.2.description}}),
                ),
                value = apps,
                onValueChange = { apps = it },
                enabled = !sending,
                labels = MonarchAppAccessPickerLabels(label = {{apps.label}}),
            )
            MonarchTextField(
                value = note,
                onValueChange = { note = it },
                label = {{note.label}},
                placeholder = {{note.placeholder}},
                helperText = {{note.helper}},
                enabled = !sending,
                singleLine = false,
            )
            MonarchButton(
                text = if (emails.size > 1) "Send ${emails.size} invites" else {{send}},
                onClick = {
                    if (emails.isEmpty()) {
                        fieldError = "Add at least one email address."
                    } else {
                        sending = true
                        scope.launch {
                            // Send emails, role, apps and note.trim() to the server. Keep the addresses it refused.
                            val refused = mapOf<String, String>()
                            sending = false
                            failures = refused
                            emails = emails.filter { it in refused }
                            if (refused.isEmpty()) open = false
                        }
                    }
                },
                modifier = Modifier.fillMaxWidth(),
                variant = MonarchButtonVariant.Primary,
                loading = sending,
            )
            MonarchButton(
                text = {{cancel}},
                onClick = { open = false },
                modifier = Modifier.fillMaxWidth(),
                variant = MonarchButtonVariant.Ghost,
                enabled = !sending,
            )
        }
    }
}

