val emailPattern = remember { Regex("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$") }
var open by rememberSaveable { mutableStateOf(true) }
var emails by rememberSaveable { mutableStateOf(listOf<String>()) }
var role by rememberSaveable { mutableStateOf<String?>({{role.value}}) }
var apps by rememberSaveable { mutableStateOf(listOf<String>()) }
var note by rememberSaveable { mutableStateOf("") }
var sending by remember { mutableStateOf(false) }
var fieldError by remember { mutableStateOf<String?>(null) }
var failures by remember { mutableStateOf(mapOf<String, String>()) }

