MonarchButton(text = "Invite people", onClick = { open = true }, variant = MonarchButtonVariant.Primary)
if (open) {
    MonarchBottomSheet(
        onDismissRequest = { open = false },
        title = "Invite people",
        description = "They’ll get an email and join once they accept the invitation.",
        dismissible = !sending,
    ) {
        Column(
            modifier = Modifier.verticalScroll(rememberScrollState()),
            verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4),
        ) {
            MonarchTagInput(
                tags = emails,
                onTagsChange = {
                    emails = it
                    fieldError = null
                    failures = failures.filterKeys { email -> email in it }
                },
                label = "Email addresses",
                required = true,
                removeIcon = {
                    MonarchIcon(imageVector = SampleIcons.Close, contentDescription = null)
                },
                enabled = !sending,
                placeholder = "name@example.com",
                helperText = "Separate several addresses with commas, spaces or new lines.",
                errorText = fieldError,
                separators = setOf(',', ' ', '\n'),
                maxCount = 50,
                normalize = { it.trim().removePrefix("<").removeSuffix(">") },
                validate = { tag, _ -> if (emailPattern.matches(tag)) null else "“$tag” is not an email address." },
            )
            if (failures.isNotEmpty()) {
                MonarchInlineNotice(
                    title = "${failures.size} addresses couldn’t be invited",
                    message = failures.entries.joinToString("\n") { (email, reason) -> "$email: $reason" },
                    tone = MonarchTone.Danger,
                )
            }
            MonarchRolePicker(
                roles = listOf(
                    MonarchRoleOption("viewer", title = "Viewer", description = "Can see everything but change nothing."),
                    MonarchRoleOption("member", title = "Member", description = "Can create and edit work."),
                    MonarchRoleOption("admin", title = "Admin", description = "Can also manage members and settings."),
                ),
                selected = role,
                onSelect = { role = it },
                layout = MonarchRolePickerLayout.Compact,
                enabled = !sending,
                label = "Role",
                required = true,
            )
            @OptIn(ExperimentalMonarchApi::class)
            MonarchAppAccessPicker(
                apps = listOf(
                    MonarchAppAccessOption("notes", "Notes", description = "Shared documents"),
                    MonarchAppAccessOption("tasks", "Tasks", description = "Projects and issues"),
                    MonarchAppAccessOption("calendar", "Calendar", description = "Shared calendars"),
                ),
                value = apps,
                onValueChange = { apps = it },
                enabled = !sending,
                labels = MonarchAppAccessPickerLabels(label = "App access"),
            )
            MonarchTextField(
                value = note,
                onValueChange = { note = it },
                label = "Personal note",
                placeholder = "Add a note to the invitation email",
                helperText = "Optional",
                enabled = !sending,
                singleLine = false,
            )
            MonarchButton(
                text = if (emails.size > 1) "Send ${emails.size} invites" else "Send invite",
                onClick = {
                    if (emails.isEmpty()) {
                        fieldError = "Add at least one email address."
                    } else {
                        sending = true
                        scope.launch {
                            // Send emails, role, apps and note.trim() to the server. Keep the addresses it refused.
                            val refused = mapOf<String, String>()
                            sending = false
                            failures = refused
                            emails = emails.filter { it in refused }
                            if (refused.isEmpty()) open = false
                        }
                    }
                },
                modifier = Modifier.fillMaxWidth(),
                variant = MonarchButtonVariant.Primary,
                loading = sending,
            )
            MonarchButton(
                text = "Cancel",
                onClick = { open = false },
                modifier = Modifier.fillMaxWidth(),
                variant = MonarchButtonVariant.Ghost,
                enabled = !sending,
            )
        }
    }
}
